pub fn advance(&mut self, delta_seconds: f32) {
    if !self.active {
        return;
    }
    self.previous_clip_time = self.clip_time;
    self.elapsed += delta_seconds.max(0.0);
    let play_rate = if self.play_rate.abs() <= 1e-8 { 0.0 } else { self.play_rate };
    self.clip_time = (self.start_time + self.elapsed * play_rate).clamp(0.0, self.duration);
    let playback_duration = if play_rate == 0.0 {
        f32::INFINITY
    } else if play_rate < 0.0 {
        self.start_time.max(0.0) / -play_rate
    } else {
        (self.duration - self.start_time).max(0.0) / play_rate
    };
    if let Some(stop_elapsed) = &mut self.stop_elapsed {
        *stop_elapsed += delta_seconds.max(0.0);
    } else {
        self.weight = transition_blend_amount(self.elapsed, self.blend_in);
        if playback_duration - self.elapsed > 1e-4 {
            return;
        }
        self.stop_with_duration(self.blend_out, false);
        return;
    }
    let stop_elapsed = self.stop_elapsed.unwrap();
    self.weight = self.stop_start_weight * (1.0 - transition_blend_amount(stop_elapsed, self.stop_duration));
    if stop_elapsed >= self.stop_duration {
        self.active = false;
        self.weight = 0.0;
    }
}

pub(crate) fn source_transition_sequence(playback: &AlsTransitionPlayback) -> Option<&'static str> {
    let left = playback.index <= 0.5;
    match playback.kind {
        AlsTransitionKind::Stop => Some(if left {
            "A_Als_Stop_Left"
        } else {
            "A_Als_Stop_Right"
        }),
        AlsTransitionKind::QuickStop => Some(if left {
            "A_Als_Stand_Transition_Left"
        } else {
            "A_Als_Stand_Transition_Right"
        }),
        AlsTransitionKind::StandingDynamic => Some(if left {
            "A_Als_Stand_DynamicTransition_Left"
        } else {
            "A_Als_Stand_DynamicTransition_Right"
        }),
        AlsTransitionKind::StandingTransition => Some(if left { "A_Als_Stand_Transition_Left" } else { "A_Als_Stand_Transition_Right" }),
        AlsTransitionKind::CrouchingDynamic => Some(if left {
            "A_Als_Crouch_DynamicTransition_Left"
        } else {
            "A_Als_Crouch_DynamicTransition_Right"
        }),
        AlsTransitionKind::CrouchingStop | AlsTransitionKind::CrouchingQuickStop => Some(if left {
            "A_Als_Crouch_Transition_Left"
        } else {
            "A_Als_Crouch_Transition_Right"
        }),
    }

pub(crate) fn sample_source_montage(
    name: &str,
    time: f32,
    assets: &SourceMontageAssets,
    clips: &Assets<bevy_animation_graph::core::animation_clip::GraphClip>,
    skeletons: &Assets<bevy_animation_graph::core::skeleton::Skeleton>,
) -> Option<(
    bevy_animation_graph::core::pose::Pose,
    AnimationContextState,
)> {
    let settings = MONTAGES.get(name)?;
    let (clip, reference) = assets.0.get(name)?;
    let time = time.min(settings.duration);
    let mut pose = crate::extensions::source_sequence_player::sample_pose(clips.get(clip)?, time);
    if let Some(reference) = reference {
        let reference = crate::extensions::source_sequence_player::sample_pose(clips.get(reference)?, 0.0);
        pose = crate::extensions::mesh_space_difference::make_mesh_space_difference(
            &reference,
            &pose,
            skeletons.get(&pose.skeleton)?,
        );
        pose.timestamp = time;
    }
    let mut context = crate::get_up::sampled_curve_context(&settings.curves, time);
    context.asset_samples.push(crate::extensions::animation_context::SourceAssetSample {
        identity: name.to_owned(), clip: clip.clone(), montage: true,
        clock: crate::extensions::SourceRelevantAsset { duration: settings.duration, position: time, weight: 1.0, ..default() },
        ..default()

fn standing_stop_completed(
    branch_seen: bool,
    previous: Option<&AlsTransitionPlayback>,
    current: Option<&AlsTransitionPlayback>,
    idle: bool,
) -> bool {
    branch_seen && previous.is_some_and(|playback| playback.clip_time > 0.8)
        && current.is_some_and(|playback| !playback.active && playback.clip_time == playback.duration)
        && idle
}
